// ===== HELPER FUNCTIONS (add if missing) =====

function computeAverageSeries(obj, bank, years) {
    if (!obj || !obj[bank]) return null;
    var vals = [];
    years.forEach(function(y) {
        var v = obj[bank][y];
        if (v != null && !isNaN(v)) vals.push(v);
    });
    if (!vals.length) return null;
    return vals.reduce(function(a, b) { return a + b; }, 0) / vals.length;
}

function computeCAGR(startVal, endVal, periods) {
    if (!startVal || !endVal || periods <= 0) return null;
    return (Math.pow(endVal / startVal, 1 / periods) - 1) * 100;
}

// Also ensure getBankBrand exists (it does later)

function getVal(bank, year, metricKey) {
    if (!bank) return null;
    var map = {
        'deposits_billions': DEP_B,
        'roe_percent': ROE_D,
        'nim_annual_percent': NIM_D,
        'ca_percent': CA_D,
        'sa_percent': SA_D,
        'branches_count': BR_D,
        'dep_per_branch_millions': DEP_PBR,
        'opex_per_branch_millions': OPEX_PBR      // ← NEW
    };
    var data = map[metricKey];
    if (!data || !data[bank]) return null;
    return data[bank][year] != null ? data[bank][year] : null;
}


function getIndustry(year, metricKey) {
    var map = {
        'roe_avg_percent': ROE_AVG,
        'nim_avg_percent': NIM_AVG,
        'ca_avg_percent': CA_AVG,
        'sa_avg_percent': SA_AVG,
        'opex_per_branch_avg': IND_OPEX_PBR,
    };
    var data = map[metricKey];
    if (!data) return null;
    return data[year] != null ? data[year] : null;
}

function median(arr) {
    if (!arr || !arr.length) return null;
    var sorted = arr.slice().sort(function(a,b){return a-b;});
    var mid = Math.floor(sorted.length/2);
    return sorted.length % 2 ? sorted[mid] : (sorted[mid-1] + sorted[mid]) / 2;
}

function rankOfYear(bank, metricKey, year) {
    var vals = BANKS.map(function(b) {
        return { b: b, v: getVal(b, year, metricKey) };
    }).filter(function(r) { return r.v != null; });
    vals.sort(function(a, z) { return z.v - a.v; });
    var idx = vals.findIndex(function(r) { return r.b === bank; });
    return { rank: idx + 1, total: vals.length };
}

function trafficLight(val, med, inv) {
    if (val == null || med == null) return 'tw-dot-yellow';
    var better = inv ? val < med : val > med;
    var diff = Math.abs(val - med);
    if (better && diff > 2) return 'tw-dot-green';
    if (!better && diff > 2) return 'tw-dot-red';
    return 'tw-dot-yellow';
}

function genTakeaways(bank, ly) {
    var sr = SUMM_DATA['5'].find(function(r) { return r.b === bank; }) || {};
    var items = [];
    function add(dot, html) { items.push({ dot: dot, html: html }); }

    // 1. Deposit CAGR
    if (sr.dep != null) {
        var cagrSum = SUMM_DATA['5'].map(function(r) { return r.dep; }).filter(function(v){return v!=null;});
        var medCagr = median(cagrSum);
        var rank = cagrSum.slice().sort(function(a,b){return b-a;}).indexOf(sr.dep) + 1;
        var dot = rank <= 8 ? 'tw-dot-green' : (rank <= 14 ? 'tw-dot-yellow' : 'tw-dot-red');
        add(dot, '<span class="tw-strong">' + bank.split(' ')[0] + '</span> deposit CAGR is <span class="tw-strong">' + sr.dep.toFixed(1) + '%</span>, ' +
            (sr.dep >= medCagr ? 'above' : 'below') + ' median of ' + (medCagr||0).toFixed(1) +
            '% by ' + Math.abs(sr.dep - (medCagr||0)).toFixed(1) + ' pp — <span class="tw-rank">#' + rank + ' of ' + cagrSum.length + '</span>');
    }

    // 2. ROE
    if (sr.roe != null) {
        var roeVals = SUMM_DATA['5'].map(function(r) { return r.roe; }).filter(function(v){return v!=null;});
        var medROE = median(roeVals);
        var rank = roeVals.slice().sort(function(a,b){return b-a;}).indexOf(sr.roe) + 1;
        add(trafficLight(sr.roe, medROE),
            'ROE is <span class="tw-strong">' + sr.roe.toFixed(1) + '%</span>, ' +
            (sr.roe >= (medROE||0) ? '<span class="tw-strong">' + (sr.roe - (medROE||0)).toFixed(1) + ' pp above</span>' :
                ((medROE||0) - sr.roe).toFixed(1) + ' pp below') +
            ' the 5Y median of ' + (medROE||0).toFixed(1) + '% — <span class="tw-rank">#' + rank + ' of ' + roeVals.length + '</span>');
    }

    // 3. CA%
    var latestCA = getVal(bank, ly, 'ca_percent');
    if (latestCA != null) {
        var r = rankOfYear(bank, 'ca_percent', ly);
        var indCA = getIndustry(ly, 'ca_avg_percent');
        add(trafficLight(latestCA, indCA),
            'CA% deposit quality: <span class="tw-strong">' + latestCA.toFixed(1) + '%</span> ' +
            (indCA != null ? (latestCA >= indCA ? '(' + ((latestCA - indCA).toFixed(1)) + ' pp above industry avg)' :
                '(' + ((indCA - latestCA).toFixed(1)) + ' pp below avg)') : '') +
            ' — <span class="tw-rank">#' + (r.rank || '?') + ' of ' + r.total + '</span>');
    }

    // 4. NIM
    if (sr.nim != null) {
        var nimVals = SUMM_DATA['5'].map(function(r) { return r.nim; }).filter(function(v){return v!=null;});
        var medNIM = median(nimVals);
        var rank = nimVals.slice().sort(function(a,b){return b-a;}).indexOf(sr.nim) + 1;
        add(trafficLight(sr.nim, medNIM),
            'NIM is <span class="tw-strong">' + sr.nim.toFixed(2) + '%</span> — ' +
            (sr.nim >= (medNIM||0) ? 'stronger' : 'weaker') + ' than median of ' + (medNIM||0).toFixed(2) +
            '% — <span class="tw-rank">#' + rank + ' of ' + nimVals.length + '</span>');
    }

    // 5. C/I
    var ci = sr.ci_latest || sr.ci;
    if (ci != null) {
        var ciVals = SUMM_DATA['5'].map(function(r) { return r.ci_latest || r.ci; }).filter(function(v){return v!=null;});
        var medCI = median(ciVals);
        var rank = ciVals.slice().sort(function(a,b){return a-b;}).indexOf(ci) + 1;
        add(trafficLight(ci, medCI, true),
            'Cost discipline: C/I is <span class="tw-strong">' + ci.toFixed(1) + '%</span> ' +
            (ci <= (medCI||0) ? '(efficient — below median)' : '(' + ((ci - (medCI||0)).toFixed(1)) + ' pp above median)') +
            ' — <span class="tw-rank">#' + rank + ' of ' + ciVals.length + '</span>');
    }

    if (items.length === 0) {
        items.push({ dot: 'tw-dot-yellow', html: 'ℹ️ Insufficient data to generate takeaways for this bank.' });
    }
    return items;
}

