function sortDC(c){if(dcSort===c)dcDir*=-1;else{dcSort=c;dcDir=-1;}buildDCT();}
function onDepSearch(val){depSearchState[depSearchKey(dcP)]=val;buildDCT();}
function buildDCT(){
  var data=dcP===0?CAGR.full:CAGR[dcP];
  var ind=DEP_IND[dcP===0?'full':dcP];
  var raw=BANKS.map(function(b){var v=data[b];return v?{b:b,c:v.cagr,s:v.start||v.from,e:v.end||v.to,n:v.n,vs:v.vs,ve:v.ve,m:v.ve&&v.vs?+(v.ve/v.vs).toFixed(1):null}:{b:b,c:null};});
  var sv=depSearchState[depSearchKey(dcP)];
  var terms=sv.split(',').map(function(t){return t.trim().toLowerCase();}).filter(function(t){return t.length>0;});
  var rows=terms.length?raw.filter(function(r){return terms.some(function(t){return r.b.toLowerCase().indexOf(t)>=0;});}):raw;
  rows.sort(function(a,z){if(!a.c&&!z.c)return 0;if(!a.c)return 1;if(!z.c)return -1;if(dcSort==='b')return a.b.localeCompare(z.b)*dcDir;var va=a[dcSort]!=null?a[dcSort]:-999,vz=z[dcSort]!=null?z[dcSort]:-999;return(va-vz)*dcDir;});
  var cnt=document.getElementById('dep-count');
  if(cnt)cnt.textContent=rows.length+' of 20 banks';
  document.getElementById('dep-cagr-note').textContent='Green = above industry CAGR ('+ind+'%) · Red = below · Click headers to sort';
  document.getElementById('dc-tbody').innerHTML=rows.map(function(r,i){
    if(!r.c)return'<tr><td class="nt">'+(i+1)+'</td><td class="bk">'+SHR(r.b)+'</td><td colspan="6" class="nt">N/A</td></tr>';
    var cls=r.c>=ind?'pgr':'pre';
    return'<tr><td class="nt">'+(i+1)+'</td><td class="bk">'+SHR(r.b)+'</td><td><span class="pill '+cls+'">'+r.c+'%</span></td><td class="nt" style="font-size:10px">'+(r.s||'—')+' → '+(r.e||'—')+'</td><td>'+(r.n||'—')+'</td><td class="nt">'+(r.vs||'—')+'B</td><td class="nt">'+(r.ve||'—')+'B</td><td><strong style="color:#2156CC">'+(r.m?r.m+'×':'—')+'</strong></td></tr>';
  }).join('');
}

