function sNIM(c){if(nlSort===c)nlDir*=-1;else{nlSort=c;nlDir=-1;}buildNIMT();}
function buildNIMT(){
  var mp={r:'l',l:'l',b:'b',a:'a4',p:'p'};var fc=mp[nlSort]||'l';
  var s=NIM_SUM.slice().sort(function(a,b){return fc==='b'?a[fc].localeCompare(b[fc])*nlDir:(a[fc]-b[fc])*nlDir;});
  document.getElementById('nim-tbody').innerHTML=s.map(function(x,i){
    var col=x.l>=5?'#197A3A':x.l>=3.5?'#2156CC':'#C42B2B';
    var vs=x.l>4.44?'<span style="color:#197A3A">+'+(x.l-4.44).toFixed(1)+'</span>':'<span style="color:#C42B2B">'+(x.l-4.44).toFixed(1)+'</span>';
    var q=NIM_QD[x.b]?NIM_QD[x.b].filter(function(v){return v!=null&&v>0;}).slice(-4):[];
    var tr=q.length>=2?(q[q.length-1]>q[0]?'<span style="color:#197A3A">▲</span>':'<span style="color:#C42B2B">▼</span>'):'—';
    var bw=Math.round(x.l/7.2*100);
    return'<tr><td class="nt">'+(i+1)+'</td><td class="bk" title="'+x.b+'">'+SHR(x.b)+'</td><td><span style="color:'+col+';font-weight:700">'+x.l+'%</span><div class="bbar"><div class="bfill" style="width:'+bw+'%;background:'+col+'"></div></div></td><td>'+vs+'</td><td>'+x.a4+'%</td><td style="color:'+col+';font-weight:600">'+x.p+'%</td><td style="color:#A8998A;font-size:10px">'+x.pq+'</td><td>'+tr+'</td></tr>';
  }).join('');
}

