var nmiP=5,nmiSort='c',nmiDir=-1,nmiInit=false;
function rNMI(){if(nmiInit)return;nmiInit=true;sNMIP(5,document.querySelector('#tab-nmi .ptab'));}
function sNMIP(p,btn){nmiP=p;document.querySelectorAll('#tab-nmi .ptab').forEach(function(t){t.classList.remove('active');});if(btn)btn.classList.add('active');buildNMIT();}
function sortNMI(c){if(nmiSort===c)nmiDir*=-1;else{nmiSort=c;nmiDir=-1;}buildNMIT();}
function buildNMIT(){
  var data=nmiP===0?NMI_FULL:nmiP===5?NMI_C5:nmiP===10?NMI_C10:NMI_C15;
  var ind=NMI_IND[nmiP===0?'full':nmiP];
  var rows=BANKS.map(function(b){var v=data[b];return v?{b:b,c:v.cagr,s:v.start||v.from,e:v.end||v.to,n:v.n,vs:v.vs,ve:v.ve,m:v.ve&&v.vs?+(v.ve/v.vs).toFixed(1):null}:{b:b,c:null};});
  rows.sort(function(a,z){if(!a.c&&!z.c)return 0;if(!a.c)return 1;if(!z.c)return -1;if(nmiSort==='b')return a.b.localeCompare(z.b)*nmiDir;var va=a[nmiSort]!=null?a[nmiSort]:-999,vz=z[nmiSort]!=null?z[nmiSort]:-999;return(va-vz)*nmiDir;});
  document.getElementById('nmi-note').textContent='Green = above industry CAGR ('+ind+'%) · Red = below · Sort by clicking headers';
  document.getElementById('nmi-tbody').innerHTML=rows.map(function(r,i){
    if(!r.c||r.c<0)return'<tr><td class="nt">'+(i+1)+'</td><td class="bk">'+SHR(r.b)+'</td><td colspan="6" class="nt">N/A</td></tr>';
    var cls=r.c>=ind?'pgr':'pre';
    return'<tr><td class="nt">'+(i+1)+'</td><td class="bk">'+SHR(r.b)+'</td><td><span class="pill '+cls+'">'+r.c+'%</span></td><td class="nt" style="font-size:10px">'+(r.s||'—')+' → '+(r.e||'—')+'</td><td>'+(r.n||'—')+'</td><td class="nt">'+(r.vs!=null?r.vs+'M':'—')+'</td><td class="nt">'+(r.ve!=null?r.ve+'M':'—')+'</td><td><strong style="color:#2156CC">'+(r.m?r.m+'×':'—')+'</strong></td></tr>';
  }).join('');
}

