  if(r25.length){document.getElementById('ci-top').textContent=r25[0].v.toFixed(1)+'%';document.getElementById('ci-tops').textContent=SHR(r25[0].b)+' · FY25';document.getElementById('ci-bot').textContent=r25[r25.length-1].v.toFixed(1)+'%';document.getElementById('ci-bots').textContent=SHR(r25[r25.length-1].b)+' · FY25';}
  buildCIChips(CI_D,CI_AVG);drawCI(CI_D,CI_AVG);rCIrank(CI_D,CI_AVG);
  MK('ci-trend',{type:'line',data:{labels:ALL_FY,datasets:[{label:'Ind Avg C/I %',data:ALL_FY.map(function(y){return CI_AVG[y]||null;}),borderColor:'#C96B2A',backgroundColor:'#C96B2A18',fill:true,pointRadius:3,tension:0.3,spanGaps:true}]},options:{plugins:{legend:{display:false}},scales:{x:G(),y:{...G(),ticks:{...Gt(),callback:function(v){return v+'%';}}}}}});
